#!/bin/bash
## Claim-10 pulse test, sea-level stage (Marcus 2026-11-17): Ladrillo L27 (v1.2) and BRICK 2.0 (B20) on the FaIR
## pulse cubes to 2500, pulses in 2030 and 2080, six markers, CO2 1 GtCO2 and CH4 0.01 GtCH4 = 24 runs per model.
## Same flags as run_vv_pulse_rerun_20261009*.sh plus --pulse-year/--end-year. Each run gates [PREFIX-MATCH] against
## the shipped 2030 run. Run from FROZEN copies; do not edit this file while it runs. Torch verdict: laptop.
set -uo pipefail
cd "$(dirname "$0")"
export OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 VECLIB_MAXIMUM_THREADS=1
LOG=$PWD/outputs/log_vv_pulse2500_20261117.txt
NPAR=3
LAD=julia/_frozen_scope_slr_pulse_vv_20261117.jl
BRK=julia/_frozen_scope_slr_pulse_vv_brick2_20261117.jl
cp julia/scope_slr_pulse_vv.jl "$LAD"; cp julia/scope_slr_pulse_vv_brick2.jl "$BRK"
[[ -n "${LADRILLO_LWS_OBS_ANCHOR:-}${LADRILLO_PALEO_ASSIGNMENT:-}${LADRILLO_GIS_SHAPE:-}" ]] &&
  { echo "the v1.1 settings must come from the code defaults: unset LADRILLO_* overrides"; exit 1; }
say(){ echo "[$(date '+%m-%d %H:%M:%S')] $*" | tee -a "$LOG"; }
step(){ local nm="$1"; shift; say "START  $nm"
  if "$@"; then say "OK     $nm"; else say "FAILED $nm (rc=$?)"; echo "$nm" >> "$LOG.fails.slr"; fi; }
psize(){ [[ "$1" == CO2 ]] && echo 1 || echo 0.01; }
rm -f "$LOG.fails.slr"
export LOG LAD BRK; export -f say step psize
one(){ local MOD=$1 Y=$2 M=$3 S=$4
  if [[ $MOD == lad ]]; then
    step "Ladrillo L27 vv$M $S $Y to2500" bash -c "julia --project=julia_v2 $LAD --marker=$M --specie=$S --pulse-size=$(psize $S) \
      --tap --tag=L27 --pulse-year=$Y --end-year=2500 > logs/lad2500_${Y}_${M}_${S}.log 2>&1"
  else
    step "BRICK 2.0 vv$M $S $Y to2500" bash -c "julia --project=julia_v2 $BRK --marker=$M --specie=$S --pulse-size=$(psize $S) \
      --ndraw=2000 --tag=B20 --pulse-year=$Y --end-year=2500 > logs/brk2500_${Y}_${M}_${S}.log 2>&1"
  fi; }
export -f one
for MOD in lad brk; do for Y in 2030 2080; do for M in VL L ML M HL H; do for S in CO2 CH4; do echo "$MOD $Y $M $S"; done; done; done; done |
  xargs -P $NPAR -L 1 bash -c 'one $0 $1 $2 $3'
say "slr phase done, $(cat "$LOG.fails.slr" 2>/dev/null | wc -l | tr -d ' ') failures"
